 7	void sc_pkcs15_free_object_content(struct sc_pkcs15_object *obj)
 8	{
 9		if (obj->content.value && obj->content.len)   {
10			if (SC_PKCS15_TYPE_AUTH & obj->type
11				|| SC_PKCS15_TYPE_SKEY & obj->type
12				|| SC_PKCS15_TYPE_PRKEY & obj->type) {
13				/* clean everything that potentially contains a secret */
14				sc_mem_clear(obj->content.value, obj->content.len);
15				sc_mem_secure_free(obj->content.value, obj->content.len);
16			} else {
17				free(obj->content.value);
18			}
19		}
20		obj->content.value = NULL;
21		obj->content.len = 0;
22	}
