25	int
26	sc_pkcs15_allocate_object_content(struct sc_context *ctx, struct sc_pkcs15_object *obj,
27			const unsigned char *value, size_t len)
28	{
29		unsigned char *tmp_buf;
30	
31		if (!obj)
32			return SC_ERROR_INVALID_ARGUMENTS;
33	
34		if (!value || !len)   {
35			sc_pkcs15_free_object_content(obj);
36			return SC_SUCCESS;
37		}
38	
39		/* Need to pass by temporary variable,
40		 * because 'value' and 'content.value' pointers can be the sames.
41		 */
42		if (SC_PKCS15_TYPE_AUTH & obj->type
43				|| SC_PKCS15_TYPE_SKEY & obj->type
44				|| SC_PKCS15_TYPE_PRKEY & obj->type) {
45			tmp_buf = sc_mem_secure_alloc(len);
46		} else {
47			tmp_buf = malloc(len);
48		}
49		if (!tmp_buf)
50			return SC_ERROR_OUT_OF_MEMORY;
51	
52		memcpy(tmp_buf, value, len);
53	
54		sc_pkcs15_free_object_content(obj);
55	
56		obj->content.value = tmp_buf;
57		obj->content.len = len;
58	
59		return SC_SUCCESS;

