165	int
166	sc_pkcs15_decode_pubkey_direct_value(struct sc_pkcs15_card *p15card, struct sc_pkcs15_object *obj)
167	{
168		struct sc_context *ctx = p15card->card->ctx;
169		struct sc_pkcs15_pubkey_info *info = (struct sc_pkcs15_pubkey_info *) obj->data;
170	
171		LOG_FUNC_CALLED(ctx);
172		if (obj->content.value == NULL || obj->content.len == 0)
173			LOG_FUNC_RETURN(ctx, SC_SUCCESS);
174	
175		if (*obj->content.value == (SC_ASN1_TAG_CONSTRUCTED | SC_ASN1_TAG_SEQUENCE))   {
176			/* RAW direct value */
177			sc_log(ctx, "Decoding 'RAW' direct value");
178			info->direct.raw.value = malloc(obj->content.len);
179			if (!info->direct.raw.value)
180				LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
181			memcpy(info->direct.raw.value, obj->content.value, obj->content.len);
182			info->direct.raw.len = obj->content.len;
183	
184			/* TODO: encode 'spki' direct value */
185		}
186	
187		if (*obj->content.value == (SC_ASN1_TAG_CONTEXT | SC_ASN1_TAG_CONSTRUCTED | 0x01))   {
188			struct sc_pkcs15_pubkey *pubkey = NULL;
189			int rv;
190	
191			/* SPKI direct value */
192			sc_log(ctx, "Decoding 'SPKI' direct value");
193			info->direct.spki.value = malloc(obj->content.len);
194			if (!info->direct.spki.value)
195				LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
196			memcpy(info->direct.spki.value, obj->content.value, obj->content.len);
197			info->direct.spki.len = obj->content.len;
198	
199			rv = sc_pkcs15_pubkey_from_spki_sequence(ctx, info->direct.spki.value, info->direct.spki.len, &pubkey);
200			LOG_TEST_RET(ctx, rv, "Failed to decode 'SPKI' direct value");
201	
202			rv = sc_pkcs15_encode_pubkey(ctx, pubkey, &info->direct.raw.value, &info->direct.raw.len);
203			sc_pkcs15_free_pubkey(pubkey);
204			LOG_TEST_RET(ctx, rv, "Failed to encode 'RAW' direct value");
205		}
206	
207		LOG_FUNC_RETURN(ctx, SC_SUCCESS);
208	}
