 14	sc_pkcs15_read_pubkey(struct sc_pkcs15_card *p15card, const struct sc_pkcs15_object *obj,
 15			struct sc_pkcs15_pubkey **out)
 16	{
 17		struct sc_context *ctx;
 18		const struct sc_pkcs15_pubkey_info *info = NULL;
 19		struct sc_pkcs15_pubkey *pubkey = NULL;
 20		unsigned char *data = NULL;
 21		size_t	len;
 22		int	algorithm, r;
 23	
 24		if (p15card == NULL || p15card->card == NULL || p15card->card->ops == NULL
 25				|| obj == NULL || out == NULL) {
 26			return SC_ERROR_INVALID_ARGUMENTS;
 27		}
 28		ctx = p15card->card->ctx;
 29	
 30		LOG_FUNC_CALLED(ctx);
 31		sc_log(ctx, "Public key type 0x%X", obj->type);
 32	
 33		switch (obj->type) {
 34		case SC_PKCS15_TYPE_PUBKEY_RSA:
 35			algorithm = SC_ALGORITHM_RSA;
 36			break;
 37		case SC_PKCS15_TYPE_PUBKEY_DSA:
 38			algorithm = SC_ALGORITHM_DSA;
 39			break;
 40		case SC_PKCS15_TYPE_PUBKEY_GOSTR3410:
 41			algorithm = SC_ALGORITHM_GOSTR3410;
 42			break;
 43		case SC_PKCS15_TYPE_PUBKEY_EC:
 44			algorithm = SC_ALGORITHM_EC;
 45			break;
 46		default:
 47			LOG_TEST_RET(ctx, SC_ERROR_NOT_SUPPORTED, "Unsupported public key type.");
 48		}
 49		info = (const struct sc_pkcs15_pubkey_info *) obj->data;
 50	
 51		pubkey = calloc(1, sizeof(struct sc_pkcs15_pubkey));
 52		if (pubkey == NULL) {
 53			LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
 54		}
 55		pubkey->algorithm = algorithm;
 56	
 57		/* starting from SPKI direct value
 58		   in a compact form it presents complete public key data */
 59		if (info->direct.spki.value && info->direct.spki.len)   {
 60			sc_log(ctx, "Using direct SPKI value,  tag 0x%X", *(info->direct.spki.value));
 61			r = sc_pkcs15_pubkey_from_spki_sequence(ctx, info->direct.spki.value, info->direct.spki.len, &pubkey);
 62			LOG_TEST_GOTO_ERR(ctx, r, "Failed to decode 'SPKI' direct value");
 63		}
 64		else if (info->direct.raw.value && info->direct.raw.len)   {
 65			sc_log(ctx, "Using direct RAW value");
 66			r = sc_pkcs15_decode_pubkey(ctx, pubkey, info->direct.raw.value, info->direct.raw.len);
 67			LOG_TEST_GOTO_ERR(ctx, r, "Failed to decode 'RAW' direct value");
 68			sc_log(ctx, "TODO: for EC keys 'raw' data needs to be completed with referenced algorithm from TokenInfo");
 69		}
 70		else if (obj->content.value && obj->content.len)   {
 71			sc_log(ctx, "Using object content");
 72			r = sc_pkcs15_decode_pubkey(ctx, pubkey, obj->content.value, obj->content.len);
 73			LOG_TEST_GOTO_ERR(ctx, r, "Failed to decode object content value");
 74			sc_log(ctx, "TODO: for EC keys 'raw' data needs to be completed with referenced algorithm from TokenInfo");
 75		}
 76		else if (p15card->card->ops->read_public_key)   {
 77			sc_log(ctx, "Call card specific 'read-public-key' handle");
 78			r = p15card->card->ops->read_public_key(p15card->card, algorithm,
 79					(struct sc_path *)&info->path, info->key_reference, info->modulus_length,
 80					&data, &len);
 81			LOG_TEST_GOTO_ERR(ctx, r, "Card specific 'read-public' procedure failed.");
 82	
 83			r = sc_pkcs15_decode_pubkey(ctx, pubkey, data, len);
 84			LOG_TEST_GOTO_ERR(ctx, r, "Decode public key error");
 85		}
 86		else if (info->path.len)   {
 87			sc_log(ctx, "Read from EF and decode");
 88			r = sc_pkcs15_read_file(p15card, &info->path, &data, &len);
 89			LOG_TEST_GOTO_ERR(ctx, r, "Failed to read public key file.");
 90	
 91			if (algorithm == SC_ALGORITHM_EC && *data == (SC_ASN1_TAG_SEQUENCE | SC_ASN1_TAG_CONSTRUCTED))
 92				r = sc_pkcs15_pubkey_from_spki_sequence(ctx, data, len, &pubkey);
 93			else
 94				r = sc_pkcs15_decode_pubkey(ctx, pubkey, data, len);
 95			LOG_TEST_GOTO_ERR(ctx, r, "Decode public key error");
 96		}
 97		else {
 98			r = SC_ERROR_NOT_IMPLEMENTED;
 99			LOG_TEST_GOTO_ERR(ctx, r, "No way to get public key");
100		}
